import { ViewTransactionDetails } from '@/Components/Feature/Backend/User/ViewTransactionDetails';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import {
    Check,
    Copy
} from 'lucide-react';
import { useState } from 'react';

export function useTransactionConfig(props: CrudPageProps): CrudConfig {

    const modelProperty = props?.modelProperty;
    const routePrefix = modelProperty?.routePrefix;

    const advanceFilterOptions = props?.advanceFilterOptions || [];


    const baseBreadcrumbs = [
        { label: 'Dashboard', href: route('backend.dashboard') },
        { label: 'Transactions', href: route(`${routePrefix}.transaction`) },
    ];

    const { t } = useTranslations();

    return {

        resource: 'transaction',
        resourcePlural: 'transactions',
        title: 'Transactions',
        description: 'All wallet transactions',

        routes: {
            index: `${routePrefix}.transaction`,
            show: `${routePrefix}.show`,
        },


        viewDisplayMode: 'modal',
        viewDialogConfig: {
            size: 'xl',
            showStats: true,
            showErrors: true,
            showDownloadButton: true,
            title: t('View'),
            description: t('Transaction details'),
            viewComponent: ViewTransactionDetails,
        },


        table: {
            selectable: false,
            searchable: true,
            sortable: true,
            serializable: true,

            searchPlaceholder: 'Search transaction no, user...',

            columns: [

                // 🔹 USER
                {
                    key: 'user',
                    label: 'User',
                    render: (row: any) => (
                        <div className="flex flex-col">
                            <span className="font-medium">{row?.user?.name}</span>
                            <span className="text-xs text-gray-500">{row?.user?.email}</span>
                        </div>
                    )
                },

                // 🔥 TRANSACTION NO + COPY
                {
                    key: 'transaction_no',
                    label: 'Transaction No',
                    render: (row: any) => {

                        const [copied, setCopied] = useState(false);

                        const copy = async () => {
                            await navigator.clipboard.writeText(row.transaction_no);
                            setCopied(true);
                            setTimeout(() => setCopied(false), 1500);
                        };

                        return (
                            <div className="flex items-center gap-2">

                                <code className="text-xs bg-muted px-2 py-1 rounded">
                                    {row.transaction_no}
                                </code>

                                <button
                                    onClick={copy}
                                    className="p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-700"
                                >
                                    {copied ? (
                                        <Check className="w-4 h-4 text-green-600" />
                                    ) : (
                                        <Copy className="w-4 h-4" />
                                    )}
                                </button>

                            </div>
                        );
                    }
                },

                // 🔥 TYPE BADGE
                {
                    key: 'type',
                    label: 'Type',
                    render: (row: any) => {

                        const map: any = {
                            deposit: {
                                label: 'Deposit',
                                class: 'bg-green-100 text-green-700'
                            },
                            withdraw: {
                                label: 'Withdraw',
                                class: 'bg-red-100 text-red-700'
                            },
                            trade_win: {
                                label: 'Trade Win',
                                class: 'bg-blue-100 text-blue-700'
                            },
                            trade_lose: {
                                label: 'Trade Lose',
                                class: 'bg-yellow-100 text-yellow-700'
                            },

                            trade_loss: {
                                label: 'Trade Loss',
                                class: 'bg-yellow-100 text-yellow-700'
                            },

                            trade_open: {
                                label: 'Trade Open',
                                class: 'bg-purple-100 text-purple-700'
                            }
                            ,
                            trade_close: {
                                label: 'Trade Close',
                                class: 'bg-pink-100 text-pink-700'
                            }
                        };

                        const item = map[row.type] || {
                            label: row.type,
                            class: 'bg-gray-100 text-gray-700'
                        };

                        return (
                            <span className={`px-2 py-1 text-xs rounded font-medium ${item.class}`}>
                                {item.label}
                            </span>
                        );
                    }
                },

                // 🔹 AMOUNT
                {
                    key: 'amount',
                    label: 'Amount',
                },

                // 🔹 BALANCE BEFORE
                {
                    key: 'balance_before',
                    label: 'Before',
                },

                // 🔹 BALANCE AFTER
                {
                    key: 'balance_after',
                    label: 'After',
                },

                // 🔹 DATE
                {
                    key: 'created_at',
                    label: 'Date',
                    renderType: 'date',
                },
            ]
        },

        filters: {
            searchFields: ['username', 'email', 'phone', 'transaction_no'],
            filterFields: advanceFilterOptions,
        },

        breadcrumbs: {
            index: baseBreadcrumbs,
        },


        permissions: {
            actions: {
                view: 'wallet.transaction.view',
            },
        },
        labels: {
            singular: 'Transaction',
            plural: 'Transactions',
            key: 'transaction',
        }
    };
}